defmodule Vetlink.Storage.Local do
  @behaviour Vetlink.Storage

  # Keys are generated by the app ("<animal_id>/<uuid>"), never taken from user input.
  # The regex check is a second line of defence against path traversal.
  @key ~r/\A[0-9]+\/[0-9a-f-]{36}\z/

  @impl true
  def put(key, bin) do
    with {:ok, path} <- path(key),
         :ok <- File.mkdir_p(Path.dirname(path)) do
      File.write(path, bin)
    end
  end

  @impl true
  def get(key) do
    with {:ok, path} <- path(key), do: File.read(path)
  end

  @impl true
  def delete(key) do
    with {:ok, path} <- path(key) do
      case File.rm(path) do
        :ok -> :ok
        {:error, :enoent} -> :ok
        other -> other
      end
    end
  end

  defp path(key) do
    if Regex.match?(@key, key),
      do: {:ok, Path.join(Application.fetch_env!(:vetlink, :storage_dir), key)},
      else: {:error, :invalid_key}
  end
end
